import {createStore,purchase,extend,confirmPayment,addCustomer,requestTrial,labels,plans} from './portal-model.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const won=n=>'₩'+Number(n).toLocaleString('ko-KR'),date=s=>s?new Date(s).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'}):'미확인';
let store,selected=30,customerId=null,extendTarget=null;
const checkout=$('#checkout'),wallet=$('#wallet'),admin=document.createElement('dialog');admin.id='admin';admin.setAttribute('aria-labelledby','admin-title');document.body.append(admin);
const adminButton=document.createElement('button');adminButton.className='outline small';adminButton.textContent='관리자 데모';$('#demo-tools').append(adminButton);adminButton.onclick=showAdmin;
const select=document.createElement('select');select.id='demo-customer';select.setAttribute('aria-label','체험할 가상 고객');$('#demo-tools').prepend(select);select.onchange=()=>customerId=select.value;
function updateSelect(){select.innerHTML='<option value="">신규 고객 체험</option>'+store.customers.map(c=>`<option value="${esc(c.id)}">${esc(c.displayName)}</option>`).join('');select.value=customerId??'';}
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),4000);}
function selectPlan(days,target=null){selected=Number(days);extendTarget=target;$('#order-plan').textContent=selected+'일 이용권';$('#order-price').textContent=won(plans[selected]);$('#checkout-title').textContent=target?'이용권 연장':'이용권 주문';$('#email').value=store.customers.find(c=>c.id===(target??customerId))?.email??'';if(wallet.open)wallet.close();checkout.showModal();}
document.querySelectorAll('[data-plan]').forEach(b=>{b.disabled=true;b.onclick=()=>selectPlan(b.dataset.plan);});
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#account').onclick=showWallet;
$('#order-form').onsubmit=e=>{e.preventDefault();try{const c=extendTarget?extend(store,extendTarget,selected):purchase(store,{customerId,email:$('#email').value,days:selected});customerId=c.id;updateSelect();checkout.close();e.target.reset();showWallet();notify('데모 주문 완료 · 실제 결제는 발생하지 않습니다');}catch(error){notify(error.message);}};
function showWallet(){if(!store)return;const c=store.customers.find(c=>c.id===customerId),box=$('#wallet-content');if(!c){box.innerHTML='<div class="pass-info"><h3>이용권을 시작해 보세요</h3><p>데모 주문 후 이용권과 접속 키를 확인할 수 있습니다</p></div><button class="primary full" id="choose-pass">요금제 선택 ↗</button>';$('#choose-pass').onclick=()=>{wallet.close();$('#plans').scrollIntoView();};}else{box.innerHTML=`<div class="pass-info"><span class="pill">${esc(labels[c.status])}</span><h3>${esc(c.displayName)}</h3><p>${esc(c.email)}</p><p>이용 종료일: <strong>${expiryDate(c.expiresAt)}</strong></p><p>접속 키: ${esc(c.keyId??'미발급')}</p>${c.status==='active'?`<code class="key">${esc(c.accessUrl)}</code><button class="outline full" id="copy-key">가상 키 복사 ⧉</button>`:'<p>결제 또는 이용기간 확인 후 키를 확인할 수 있습니다</p>'}</div><p class="fine">가상 고객 화면이며, 키로 실제 VPN에 연결할 수 없습니다</p><div class="wallet-actions"><button class="primary" id="extend">구매·연장</button><a class="button outline" href="https://getoutline.org/get-started/" target="_blank" rel="noopener">앱 설치 안내 ↗</a></div><h3 class="subheading">주문 내역</h3><div class="order-list">${store.orders.filter(o=>o.customerId===c.id).map(o=>`<div><span>${o.type==='trial'?'무료 1일 체험':o.days+'일 이용권'} · 확인 완료<small>${date(o.createdAt)}</small></span><strong>${won(o.amount)}</strong></div>`).join('')||'<p>이전 결제 기록은 아직 등록되지 않았습니다</p>'}</div>`;$('#extend').onclick=()=>selectPlan(30,c.id);if(c.status==='active')$('#copy-key').onclick=async()=>{try{await navigator.clipboard.writeText(c.accessUrl);notify('가상 키를 복사했습니다');}catch{notify('표시된 키를 직접 선택해 주세요');}};}if(!wallet.open)wallet.showModal();}
function showAdmin(){if(!store)return;admin.innerHTML=`<button class="close" aria-label="관리자 창 닫기">×</button><div class="eyebrow">ADMIN WORKSPACE · DEMO</div><h2 id="admin-title">고객과 이용권 관리</h2><p class="fine">가상 기준일 ${date(store.now)} · 새로고침하면 변경 내용이 초기화됩니다</p><div class="metrics"><div><span>전체 고객</span><strong>${store.customers.length}</strong></div><div><span>이용 중</span><strong>${store.customers.filter(c=>c.status==='active').length}</strong></div><div><span>결제대기</span><strong>${store.customers.filter(c=>c.status==='payment_pending').length}</strong></div><div><span>확인 필요</span><strong>${store.customers.filter(c=>['expired','review_required'].includes(c.status)).length}</strong></div></div><div class="filters"><input id="search" type="search" placeholder="고객명·이메일·키 검색" aria-label="고객 검색"><select id="status-filter" aria-label="상태 필터"><option value="">전체 상태</option>${Object.entries(labels).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></div><div class="table-scroll"><table><thead><tr><th>고객</th><th>상태</th><th>접속 키</th><th>만료일</th><th>관리</th></tr></thead><tbody id="customer-rows"></tbody></table></div><details class="register"><summary>가상 고객 추가</summary><form id="add-customer"><label>고객명<input name="customerName" required maxlength="60" placeholder="가상 고객 이름"></label><label>이메일<input name="email" type="email" required placeholder="demo@example.test"></label><button class="primary">고객 등록</button></form></details><h3 class="subheading">최근 작업</h3>${store.audit.slice().reverse().slice(0,8).map(a=>`<p class="fine">${date(a.at)} · ${esc(a.message)}</p>`).join('')||'<p class="fine">아직 작업 이력이 없습니다</p>'}`;admin.querySelector('.close').onclick=()=>admin.close();$('#search').oninput=renderRows;$('#status-filter').onchange=renderRows;$('#add-customer').onsubmit=e=>{e.preventDefault();try{addCustomer(store,{name:e.target.elements.customerName.value,email:e.target.elements.email.value});updateSelect();showAdmin();notify('가상 고객을 등록했습니다');}catch(error){notify(error.message);}};renderRows();if(!admin.open)admin.showModal();}
function renderRows(){const query=$('#search').value.toLowerCase(),status=$('#status-filter').value;const list=store.customers.filter(c=>(!status||c.status===status)&&`${c.displayName} ${c.email} ${c.keyId}`.toLowerCase().includes(query));$('#customer-rows').innerHTML=list.map(c=>`<tr><td><strong>${esc(c.displayName)}</strong><small>${esc(c.email)}</small></td><td><span class="badge ${esc(c.status)}">${esc(labels[c.status])}</span></td><td>${esc(c.keyId??'미발급')}</td><td>${expiryDate(c.expiresAt)}</td><td><button class="row-action" data-action="view" data-id="${esc(c.id)}">보기</button><button class="row-action" data-action="${c.status==='payment_pending'?'confirm':'extend'}" data-id="${esc(c.id)}">${c.status==='payment_pending'?'수납 확인':'30일 연장'}</button></td></tr>`).join('')||'<tr><td colspan="5">조건에 맞는 고객이 없습니다</td></tr>';$('#customer-rows').querySelectorAll('button').forEach(b=>b.onclick=()=>{try{if(b.dataset.action==='view'){customerId=b.dataset.id;updateSelect();admin.close();showWallet();return;}if(b.dataset.action==='confirm')confirmPayment(store,b.dataset.id);else extend(store,b.dataset.id,30);showAdmin();notify('가상 이용권에 반영했습니다');}catch(error){notify(error.message);}});}
fetch('./demo-data.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{store=createStore(data);updateSelect();$('#request-trial').disabled=false;document.querySelectorAll('[data-plan]').forEach(b=>b.disabled=false);}).catch(()=>notify('가상 데이터를 불러오지 못했습니다 새로고침해 주세요'));

function expiryDate(value){return value?new Date(value).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})+' (한국시간)':'미확인';}
const trialDialog=$('#trial-dialog');
$('#request-trial').onclick=()=>{if(!store)return;$('#trial-error').textContent='';$('#trial-form').reset();$('#trial-email').value=store.customers.find(c=>c.id===customerId)?.email??'';trialDialog.showModal();};
$('#trial-form').onsubmit=e=>{e.preventDefault();try{const c=requestTrial(store,{customerId,email:$('#trial-email').value});customerId=c.id;updateSelect();trialDialog.close();showWallet();notify('무료 24시간 체험을 신청했습니다 현재는 가상 키입니다');}catch(error){$('#trial-error').textContent=error.message;}};
